@pytest.mark.asyncio
async def test_validation_ssrf_allowlisted_loopback() -> None:
    """SSRF allowlist permits a loopback mock server while private-network protection remains enabled."""
    engine_config = CrawlConfig(
        respect_robots_txt=False,
        ssrf=SsrfPolicy(allowlist=[{"type": "cidr", "value": "127.0.0.0/8"}], deny_private=True, max_redirects=5),
        ssrf_deny_private_explicit=True,
    )
    engine = create_engine(engine_config)
    url = os.environ["MOCK_SERVER_URL"] + "/fixtures/validation_ssrf_allowlisted_loopback"

    result = await scrape(engine, url)
    assert result.status_code == 200
    assert result.metadata.title == "Allowlisted"


@pytest.mark.asyncio
async def test_validation_ssrf_ipv4_mapped_ipv6_denied() -> None:
    """SSRF policy rejects an IPv4 loopback address embedded in an IPv6 literal."""
    with pytest.raises(Exception) as exc_info:
        engine_config = CrawlConfig(ssrf=SsrfPolicy(deny_private=True), ssrf_deny_private_explicit=True)
        engine = create_engine(engine_config)
        url = "http://[::ffff:127.0.0.1]/"
        await scrape(engine, url)
    assert "ssrf_policy_violation" in str(exc_info.value) or "ssrf_policy_violation" in type(exc_info.value).__name__


